export function Icon({ name, size = 24, className }: IconProps) {
  const style = {
    '--icon-size': typeof size === 'number' ? String(size) + 'px' : size,
  } as CSSProperties;

  return (
    <svg
      aria-hidden="true"
      className={['icon', className].filter(Boolean).join(' ')}
      fill="none"
      focusable="false"
      style={style}
      viewBox="0 0 24 24"
    >
      {iconPaths[name].map((pathProps, index) => (
        <path key={index} {...pathProps} />
      ))}
    </svg>
  );
}
